#!/usr/bin/env python3import osimport sysimport timeimport jsonimport argparseimport subprocessfrom pathlib import Pathfrom gui.ConfigData import ConfigDatatry:    import psutilexcept ImportError:    print("Please install psutil: pip install psutil")    sys.exit(1)def kill_carla_processes():    """Kill any CarlaUE4-Shipping.exe or CarlaUE4.exe processes."""    for proc in psutil.process_iter(["name"]):        name = proc.info["name"]        if name in ("CarlaUE4-Win64-Shipping.exe", "CarlaUE4.exe", "CarlaUE4-Linux-Shipping", "CarlaUE4.sh"):            try:                proc.kill()                print(f"Killed {name} (pid {proc.pid})")            except psutil.NoSuchProcess:                passdef start_carla(executable_path: str):    """    Launch CARLA headless in its own process group.    On Windows uses CREATE_NEW_PROCESS_GROUP,    on POSIX uses setsid().    """    cmd = [executable_path, "-RenderOffScreen"]    if sys.platform.startswith("win"):        # Windows: put in new process group so we can kill just Carla        subprocess.Popen(cmd, creationflags=subprocess.CREATE_NEW_PROCESS_GROUP)    else:        # POSIX: setsid() starts the process in a new session & process group        subprocess.Popen(cmd, preexec_fn=os.setsid)